window.MNEMIKA_LANG_KEYS={"de": {"lang.deOnly": "Dieses Kapitel liegt bisher nur auf Deutsch vor.", "lang.coverage": "Kapitel in dieser Sprache", "lang.deChapter": "nur Deutsch"}, "en": {"lang.deOnly": "This chapter is currently available in German only.", "lang.coverage": "chapters in this language", "lang.deChapter": "German only"}, "fr": {"lang.deOnly": "Ce chapitre n'existe pour l'instant qu'en allemand.", "lang.coverage": "chapitres dans cette langue", "lang.deChapter": "allemand seulement"}};
(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
 var K=window.MNEMIKA_LANG_KEYS;
 ["de","en","fr"].forEach(function(l){ M.I18N[l]=Object.assign(M.I18N[l]||{},K[l]); });

 /* Sichtbarer Umfang in der Kopfzeile, sobald eine andere Sprache aktiv ist. */
 function paintCoverage(){
   var l=M.locale?M.locale():"de";
   var box=document.getElementById("mn-langcov");
   var bar=document.querySelector(".top-in");
   if(!bar) return;
   if(!box){ box=document.createElement("span"); box.id="mn-langcov"; box.className="langcov";
     var h=document.querySelector(".hdlang");
     if(h&&h.parentNode) h.parentNode.insertBefore(box,h.nextSibling); else bar.appendChild(box); }
   if(l==="de"){ box.hidden=true; return; }
   var c=M.languageCoverage(l);
   box.hidden=false;
   box.textContent=c.available+"/"+c.total;
   box.title=M.t("lang.coverage")+": "+c.percent+"%";
 }
 M.paintLanguageCoverage=paintCoverage;
 var sl=M.setLocale;
 if(typeof sl==="function"){ M.setLocale=function(id){ var r=sl.call(M,id);
   setTimeout(paintCoverage,0); return r; }; }
 var go0=M.go;
 if(typeof go0==="function"){ M.go=function(){ var r=go0.apply(this,arguments);
   setTimeout(paintCoverage,0); return r; }; }
 setTimeout(paintCoverage,400); setTimeout(paintCoverage,1400);
 })();

