(function(){"use strict";var M=window.MNEMIKA;if(!M)return;

/* ---------- Betreiberangaben. Ohne diese Werte darf derzeit keine Werbung laufen. ---------- */
M.OPERATOR = {
  legalName: "", street: "", postcode: "", city: "", country: "Schweiz",
  email: "", uid: "", responsible: "", domain: "stoffknacker.com"
};
M.operatorComplete = function () {
  var r = ["legalName","street","postcode","city","email","responsible"];
  return r.every(function (k) { return String(M.OPERATOR[k] || "").trim().length > 0; });
};
M.operatorMissing = function () {
  var r = {legalName:"Betreiberin oder Betreiber", street:"Strasse und Nummer",
    postcode:"Postleitzahl", city:"Ort", email:"Kontakt-E-Mail",
    responsible:"Verantwortlich für den Inhalt"};
  return Object.keys(r).filter(function (k) { return !String(M.OPERATOR[k]||"").trim(); })
    .map(function (k) { return r[k]; });
};
/* Werbung erst, wenn Betreiberangaben und Einwilligung vorliegen. */
M.adsAllowed = function () { return M.operatorComplete() && M.consentGiven() === "granted"; };
M.consentGiven = function () {
  try { return localStorage.getItem("mnemika-consent") || "unset"; } catch (e) { return "unset"; }
};
M.setConsent = function (v) {
  try { localStorage.setItem("mnemika-consent", v); } catch (e) {}
  if (M.paintFooterOld) M.paintFooterOld();
};

/* ---------- Rechtsseiten ---------- */
M.LEGAL = {
  impressum: function () {
    var o = M.OPERATOR;
    if (!M.operatorComplete()) {
      return '<p class="warnt"><b>Impressum unvollständig.</b> Ohne diese Angaben darf die Seite '
        + 'derzeit keine Werbung ausspielen: ' + M.esc(M.operatorMissing().join(", ")) + '.</p>';
    }
    return '<p>' + M.esc(o.legalName) + '<br>' + M.esc(o.street) + '<br>'
      + M.esc(o.postcode + " " + o.city) + '<br>' + M.esc(o.country) + '</p>'
      + '<p>E-Mail: ' + M.esc(o.email) + (o.uid ? '<br>UID: ' + M.esc(o.uid) : '') + '</p>'
      + '<p>Verantwortlich für den Inhalt: ' + M.esc(o.responsible) + '</p>';
  },
  privacy: function () {
    return '<h3>Was gespeichert wird</h3>'
      + '<p>Dein Lernstand bleibt in deinem Browser. Es gibt kein Benutzerkonto und keine '
      + 'Übertragung deiner Antworten an einen Server.</p>'
      + '<h3>Werbung</h3>'
      + '<p>Diese Seite kann Werbung von Google AdSense ausspielen. Google und dessen Partner '
      + 'setzen dafür Cookies oder vergleichbare Kennungen ein und verarbeiten Daten wie '
      + 'IP-Adresse, Gerät, Browser und aufgerufene Seiten, um Anzeigen auszuliefern, '
      + 'Reichweite zu messen und Missbrauch zu erkennen. Rechtsgrundlage in der EU und im EWR '
      + 'ist deine Einwilligung nach Art. 6 Abs. 1 lit. a DSGVO, in der Schweiz gilt das DSG.</p>'
      + '<p>Du kannst die Einwilligung jederzeit unten auf dieser Seite widerrufen. '
      + 'Personalisierte Werbung lässt sich zusätzlich in den Google-Anzeigeneinstellungen abschalten.</p>'
      + '<h3>Empfänger</h3><p>Google Ireland Limited und die von Google eingesetzten Partner. '
      + 'Eine Übermittlung in die USA ist möglich.</p>'
      + '<h3>Deine Rechte</h3><p>Auskunft, Berichtigung, Löschung, Einschränkung, Widerspruch '
      + 'und Datenübertragbarkeit. Wende dich dafür an die im Impressum genannte Adresse. '
      + 'Du kannst dich zudem bei der zuständigen Aufsichtsbehörde beschweren, in der Schweiz '
      + 'beim EDÖB.</p>'
      + '<h3>Lernstand löschen</h3><p>Über Menü, Lernstand sichern, Zurücksetzen entfernst du '
      + 'alle lokal gespeicherten Daten.</p>';
  },
  terms: function () {
    return '<p>Stoffknacker ist ein Lern- und Übungsangebot. Die Inhalte ersetzen keine amtliche '
      + 'Auskunft und keinen Unterricht. Massgebend sind allein die Prüfungsreglemente und '
      + 'Lehrpläne der zuständigen Stellen.</p>'
      + '<p>Für Gymnasiale Maturität, Schweizerische Maturitätsprüfung, Berufsmaturität, '
      + 'EBMP sowie Fachmittelschule und Fachmaturität ist der Lehrplanabgleich noch nicht '
      + 'abgeschlossen. Für diese Wege weist Stoffknacker keine Prüfungsbereitschaft aus.</p>'
      + '<p>Die Nutzung erfolgt auf eigene Verantwortung. Eine Haftung für Schäden aus der '
      + 'Nutzung wird im gesetzlich zulässigen Rahmen ausgeschlossen.</p>';
  }
};
})();

