M.LEGAL_VERSION="2026-11-07";
M.CONSENT_VERSION=2;

/* Einwilligung mit Nachweis: Zeitpunkt, Fassung, Zwecke einzeln. */
M.PURPOSES=[
 {id:"necessary", required:true},
 {id:"ads"},
 {id:"adsPersonal"},
 {id:"measure"}
];
M.consentRecord=function(){
 try{ return JSON.parse(localStorage.getItem("mnemika-consent-record")||"null"); }catch(e){ return null; }
};
M.setConsentRecord=function(purposes){
 var rec={version:M.CONSENT_VERSION, legalVersion:M.LEGAL_VERSION,
   at:new Date().toISOString(), purposes:purposes, minor:M.isMinor()};
 try{ localStorage.setItem("mnemika-consent-record", JSON.stringify(rec));
      localStorage.setItem("mnemika-consent", purposes.ads?"granted":"denied"); }catch(e){}
 return rec;
};
/* Alter: ein Prüfungstrainer hat Nutzende unter 18. Ohne bestätigte
   Volljährigkeit gilt die vorsichtige Annahme. */
M.ageDeclared=function(){ try{ return localStorage.getItem("mnemika-age")||""; }catch(e){ return ""; } };
M.setAge=function(v){ try{ localStorage.setItem("mnemika-age", v); }catch(e){}
  if(M.paintFooter) M.paintFooter(); };
M.isMinor=function(){ return M.ageDeclared()!=="adult"; };
/* Personalisierte Werbung nie für Minderjährige, unabhängig von der Einwilligung. */
M.personalizedAdsAllowed=function(){
 var r=M.consentRecord();
 return !!(r && r.purposes && r.purposes.adsPersonal) && !M.isMinor()
   && (M.operatorComplete?M.operatorComplete():false);
};
M.adsAllowed=function(){
 var r=M.consentRecord();
 return !!(r && r.purposes && r.purposes.ads) && (M.operatorComplete?M.operatorComplete():false);
};
M.adRequestMode=function(){
 if(!M.adsAllowed()) return "none";
 return M.personalizedAdsAllowed() ? "personalized" : "non-personalized";
};

