(function(){"use strict";var M=window.MNEMIKA;if(!M)return;

/* ============================================================
   Antwortpositionen ausgleichen.
   Vorher lagen 468 von 746 richtigen Antworten auf Position 2 und nur 8
   auf Position 4. Wer immer B tippt, liegt damit weit ueber dem Zufall.
   Die Reihenfolge wird deterministisch aus der Fragekennung abgeleitet,
   also bei jedem Laden gleich, aber ueber alle Fragen gleichmaessig verteilt.
   ============================================================ */
function hash(s){var n=0; s=String(s);
 for(var i=0;i<s.length;i++){n=((n<<5)-n+s.charCodeAt(i))|0;} return Math.abs(n);}

M.balanceAnswers=function(){
 var moved=0, skipped=0, idx=0;
 /* Direkt auf den Kapiteldaten arbeiten. allQuestions liefert Kopien,
    eine Aenderung daran bleibt folgenlos. */
 var list=[];
 M.chapters.forEach(function(c){
  (c.questions||[]).forEach(function(q){ list.push(q); });
  (c.blocks||[]).forEach(function(b){ if(b&&b.check) list.push(b.check); });
 });
 list.forEach(function(q){
  idx++;
  if(!q || q.type!=="mc") return;
  var opts=q.options||q.opts;
  if(!Array.isArray(opts) || opts.length<2) return;
  if(typeof q.answer!=="number") { skipped++; return; }
  /* Antworten wie "alle der genannten" oder "keine davon" muessen hinten bleiben */
  var last=String(opts[opts.length-1]||"").toLowerCase();
  if(/alle|keine|beides|weder/.test(last)) { skipped++; return; }
  var want=hash((q.id||"")+"|"+idx) % opts.length;
  var cur=q.answer;
  if(want===cur) return;
  var tmp=opts[cur]; opts[cur]=opts[want]; opts[want]=tmp;
  if(!q.__perm){try{Object.defineProperty(q,"__perm",{value:opts.map(function(_,i){return i;}),enumerable:false,writable:true,configurable:true});}catch(e){}}
  if(q.__perm){var tp=q.__perm[cur];q.__perm[cur]=q.__perm[want];q.__perm[want]=tp;}
  ["why","optionFeedback","feedback","optionHints","distractorWhy"].forEach(function(k){var a=q[k];if(Array.isArray(a)&&a.length===opts.length){var t=a[cur];a[cur]=a[want];a[want]=t;}});
  q.answer=want;
  moved++;
 });
 return {moved:moved, skipped:skipped, seen:list.length};
};
M.answerDistribution=function(){
 var pos={};
 M.chapters.forEach(function(c){
  var all=(c.questions||[]).concat((c.blocks||[]).map(function(b){return b&&b.check;}).filter(Boolean));
  all.forEach(function(q){
   if(q && q.type==="mc" && typeof q.answer==="number") pos[q.answer]=(pos[q.answer]||0)+1;});});
 var vals=Object.keys(pos).map(function(k){return pos[k];});
 var total=vals.reduce(function(a,b){return a+b;},0);
 var max=Math.max.apply(null,vals), min=Math.min.apply(null,vals);
 return {positions:pos, total:total, max:max, min:min,
   spread: total? Math.round((max-min)/total*1000)/10 : 0};
};
/* Einmal beim Start, bevor die erste Frage gezeigt wird. */
/* Die Kapiteldaten werden nach diesem Block noch einmal aufgebaut.
   Deshalb erst ausgleichen, wenn sie stehen, und nur einmal. */
M.__balanced=null;
/* Der fruehe Lauf trifft eine Kapitelliste, die danach ersetzt wird.
   Deshalb pruefen wir das Ergebnis und laufen erneut, solange die
   Verteilung noch schief ist. */
M.ensureBalanced=function(force){
 if(M.__balanced && !force) return M.__balanced;
 if(!M.chapters||!M.chapters.length) return null;
 M.__balanced=M.balanceAnswers();
 return M.__balanced;
};
M.balanceSpread=function(){ var d=M.answerDistribution(); return d.spread; };
(function settle(n){
 if(n>80) return;
 if(M.chapters&&M.chapters.length){
  if(M.balanceSpread()>12){ M.ensureBalanced(true); }
  else if(M.__balanced) return;          /* ausgeglichen und stabil */
 }
 setTimeout(function(){settle(n+1);},120);
})(0);
})();

