(function(){"use strict";var M=window.MNEMIKA;if(!M)return;
var E=M.esc||function(s){return String(s==null?"":s);};

/* ============================================================
   Darstellungsformen fuer den Lernstoff. Bisher war fast alles
   Absatz auf Absatz. Ein Vergleich liest sich als Tabelle besser,
   ein Verfahren als nummerierte Karte, ein Grundsatz als Merksatz.
   ============================================================ */
M.PRESENT={

 /* Zwei Dinge nebeneinander, Zeile fuer Zeile am selben Kriterium. */
 compare:function(d){
  return '<figure class="pv pv-cmp"><figcaption>'+E(d.title||"Gegenüberstellung")+'</figcaption>'
   +'<table><thead><tr><th>Kriterium</th><th>'+E(d.a)+'</th><th>'+E(d.b)+'</th></tr></thead><tbody>'
   +(d.rows||[]).map(function(r){
     return '<tr><td class="pv-k">'+E(r[0])+'</td><td>'+E(r[1])+'</td><td>'+E(r[2])+'</td></tr>';}).join("")
   +'</tbody></table>'+(d.note?'<p class="pv-note">'+E(d.note)+'</p>':'')+'</figure>';},

 /* Ein Verfahren als Schrittfolge, jeder Schritt mit seinem Zweck. */
 procedure:function(d){
  return '<figure class="pv pv-proc"><figcaption>'+E(d.title||"So gehst du vor")+'</figcaption><ol>'
   +(d.steps||[]).map(function(s,i){
     return '<li><span class="pv-n">'+(i+1)+'</span><div><b>'+E(s.do||s[0]||"")+'</b>'
      +(s.why||s[1]?'<span>'+E(s.why||s[1])+'</span>':'')+'</div></li>';}).join("")
   +'</ol></figure>';},

 /* Ein Satz, den man behalten soll. Nichts drumherum. */
 maxim:function(d){
  return '<figure class="pv pv-max"><blockquote>'+E(d.text)+'</blockquote>'
   +(d.why?'<figcaption>'+E(d.why)+'</figcaption>':'')+'</figure>';},

 /* Formel mit Bedeutung jedes Zeichens. */
 formula:function(d){
  return '<figure class="pv pv-form"><div class="pv-eq">'+E(d.equation)+'</div>'
   +'<dl>'+(d.terms||[]).map(function(t){
     return '<dt>'+E(t[0])+'</dt><dd>'+E(t[1])+'</dd>';}).join("")+'</dl>'
   +(d.when?'<p class="pv-note"><b>Wann:</b> '+E(d.when)+'</p>':'')+'</figure>';},

 /* Haeufiger Irrtum neben der richtigen Fassung. */
 misconception:function(d){
  return '<figure class="pv pv-mis">'
   +'<div class="pv-wrong"><span>Verbreitet, aber falsch</span><p>'+E(d.wrong)+'</p></div>'
   +'<div class="pv-right"><span>So stimmt es</span><p>'+E(d.right)+'</p></div>'
   +(d.why?'<p class="pv-note">'+E(d.why)+'</p>':'')+'</figure>';},

 /* Beispiel und Gegenbeispiel, damit die Grenze sichtbar wird. */
 boundary:function(d){
  return '<figure class="pv pv-bnd"><figcaption>'+E(d.title||"Wo die Grenze liegt")+'</figcaption>'
   +'<div class="pv-two"><div><span class="pv-tag ok">gehört dazu</span><ul>'
   +(d.inside||[]).map(function(x){return '<li>'+E(x)+'</li>';}).join("")+'</ul></div>'
   +'<div><span class="pv-tag no">gehört nicht dazu</span><ul>'
   +(d.outside||[]).map(function(x){return '<li>'+E(x)+'</li>';}).join("")+'</ul></div></div>'
   +(d.rule?'<p class="pv-note"><b>Die Regel:</b> '+E(d.rule)+'</p>':'')+'</figure>';},

 /* Frage, die zum Weiterdenken zwingt, mit aufklappbarer Antwort. */
 probe:function(d){
  return '<details class="pv pv-probe"><summary>'+E(d.question)+'</summary>'
   +'<div>'+E(d.answer)+'</div></details>';}
};

M.presentationTypes=function(){ return Object.keys(M.PRESENT); };
M.renderPresentation=function(kind,data){
 var f=M.PRESENT[kind]; return f?f(data):"";
};
/* Reine Absatzfolgen auflockern: ein Block, der nur Text ist, bekommt
   je nach Inhalt eine passendere Form angeboten. */
M.suggestPresentation=function(text){
 var t=String(text||"");
 if(/\bversus\b|\bgegenüber\b|\bim Unterschied\b|\bwährend\b/i.test(t)) return "compare";
 if(/\bzuerst\b.*\bdann\b|\bSchritt\b/i.test(t)) return "procedure";
 if(/\bFaustregel\b|\bmerke\b|\bimmer gilt\b/i.test(t)) return "maxim";
 if(/=/.test(t) && /[a-zA-Z]\s*=/.test(t)) return "formula";
 if(/\bIrrtum\b|\bfälschlich\b|\bviele glauben\b/i.test(t)) return "misconception";
 return null;
};
})();

