M.V44=PACK;M.version="44.1.0";M.build="2026-09-20-gitlab";if(M.FEATURE_ANCHOR)M.FEATURE_ANCHOR.contractVersion="44.0-engagement-no-regression";
function clone(x){return JSON.parse(JSON.stringify(x));}
function uniq(a,v){if(a.indexOf(v)<0)a.push(v);}
PACK.chapters.forEach(function(ch){if(!M.chapter(ch.id))M.addChapter(clone(ch));});
function addV44Variety(c,items){if(!c||!items)return;c.questions=c.questions||[];items.forEach(function(q){if(!c.questions.some(function(x){return x.id===q.id;}))c.questions.push(clone(q));});}
(PACK.legacyQuestionAugmentations||[]).forEach(function(x){addV44Variety(M.chapter(x.chapterId),x.questions);});
if(M.V41_CHAPTERS_DE)(PACK.legacyQuestionAugmentations||[]).forEach(function(x){var c=M.V41_CHAPTERS_DE.filter(function(y){return y.id===x.chapterId;})[0];addV44Variety(c,x.questions);});
var HINTS={mc:'Prüfe jede Antwort an Begriff und Voraussetzung.',tf:'Suche ein Gegenbeispiel oder eine klare Definition.',multi:'Mehrere Aussagen können gleichzeitig zutreffen.',match:'Ordne zuerst die sichersten Paare zu.',complete:'Lies den ganzen Satz und prüfe Grammatik und Fachlogik.',claim:'Trenne Behauptung, Beleg und Begründung.',justify:'Entscheide zuerst und begründe danach mit einem Fachbegriff.',finderror:'Gehe Schritt für Schritt und markiere den ersten Fehler.',order:'Bestimme Voraussetzung und Folge.',keywords:'Verbinde mindestens drei Kernbegriffe in ganzen Sätzen.',numeric:'Notiere Gegebenes, Formel, Einheit und Kontrolle.',estimate:'Nutze einen bekannten Vergleichswert als Anker.',label:'Orientiere dich an Funktion und Lage.'};
M.v44ApplyHints=function(){
 (M.chapters||[]).forEach(function(c){
  var all=(c.questions||[]).slice();
  (c.blocks||[]).forEach(function(b){if(b.check)all.push(b.check);});
  all.forEach(function(q){
   var title=String(c.title||'dieses Kapitel');
   var context=String(q.ref||q.skill||q.prompt||'diese Aufgabe').replace(/[«»"']/g,'').slice(0,52);
   var base=HINTS[q.type]||'Kläre Begriffe, Vorgehen und Kontrolle.';
   if(!String(q.hint||'').trim())q.hint=base+' Denke dabei an «'+title+'».';
   var hx=String(q.hint||'');
   var genericHints=[
    'Nutze diese Denkstruktur: Was ist es? Wie funktioniert es? Woran erkennst du es? Welche Folge oder Anwendung hat es?',
    'Beginne mit Einordnung oder Gegebenem. Danach folgen Mechanismus oder Rechnung. Die Prüfung und Deutung gehören ans Ende.',
    'Nenne nicht nur das Ergebnis. Baue eine Ursache-Wirkungs-Kette auf: Ausgangslage, Mechanismus, Zwischenschritt und beobachtbare Folge.'
   ];
   if(genericHints.indexOf(hx)>=0)q.hint=hx+' Wende sie konkret auf «'+title+'» an.';
   var ex=String(q.explanation||'');
   var genericExplanations=[
    'Eine gute Lösung ist nachvollziehbar, passend und kontrolliert.',
    'Die drei Phasen machen den Lösungsweg nachvollziehbar.',
    'Der Algorithmus verbindet Einordnung, Bearbeitung und Prüfung.',
    'Begründung und Beleg machen die Leistung bewertbar.',
    'Die Reihenfolge verhindert vorschnelle Antworten.',
    'Gegenbelege dürfen nicht ignoriert werden; sie können die Schlussfolgerung ändern.',
    'Eine tragfähige Erklärung verbindet Begriffe, Vorgehen und Kontrolle.',
    'Nenne den Begriff, erkläre, wie er wirkt, und zeige eine Anwendung. Vergleiche deine Formulierung mit der Musterantwort und ergänze fehlende Fachbegriffe.',
    'Die Reihenfolge führt vom Ausgangspunkt über die fachliche Verarbeitung zur Kontrolle. Sie ist zugleich dein Arbeitsalgorithmus für neue Aufgaben.',
    'Eine vollständige Prüfungsantwort zeigt nicht nur was, sondern auch warum.',
    'Die Reihenfolge führt von der Einordnung zur überprüfbaren Lösung.',
    'Plausibilität ersetzt weder Voraussetzungen noch Kontrolle.',
    'Der dritte Schritt überspringt die notwendige Kontrolle.',
    'Die Zuordnung trennt Gegebenes, Bearbeitung und Prüfung.',
    'Eine belastbare Lösung macht Voraussetzungen sichtbar und prüft ihr Ergebnis.',
    'Der Arbeitsweg verhindert, dass eine plausible Antwort ohne Begründung stehen bleibt.',
    'Nenne die Begriffe, beschreibe das Vorgehen und zeige eine Anwendung.',
    'Die Reihenfolge führt von Einordnung und Modell über Bearbeitung zu Kontrolle und Urteil.'
   ];
   if(genericExplanations.indexOf(ex)>=0||ex.indexOf('Anwendung, Transfer und Qualitätskontrolle wird')===0)q.explanation=ex+' Hier wird das am Inhalt von «'+title+'» geprüft.';
   /* R08: Die Laufzeitumschreibung der Antwortoptionen ist entfernt. Sie hat falsche Optionen mit
   fachfremden Zusaetzen versehen, zum Beispiel physikalische Bedingungen in franzoesischen Aufgaben.
   Erklaerungen werden weiterhin ergaenzt, die Optionen bleiben unveraendert, wie sie verfasst wurden. */
    if(!Array.isArray(q.options))return;
  });
 });
};
M.v44ApplyHints();
if(M.V41_CHAPTERS_DE)PACK.chapters.forEach(function(ch){if(!M.V41_CHAPTERS_DE.some(function(x){return x.id===ch.id;}))M.V41_CHAPTERS_DE.push(clone(ch));});
var localeV44=M.setLocale;if(typeof localeV44==='function'){M.setLocale=function(id){var r=localeV44.call(M,id);setTimeout(M.v44ApplyHints,0);return r;};}
var plans=(M.CURRICULUM_INGEST_V1&&M.CURRICULUM_INGEST_V1.resolvedPlans)||M.RESOLVED_PLANS||[];
PACK.seriesMeta.forEach(function(meta){
  var broad=M.chapter(meta.currentChapterId); if(!broad)return;
  plans.forEach(function(p){
    var matches=(broad.programmeMappings||[]).some(function(pm){return pm.programmeId===p.programmeId&&(!pm.configurationIds||pm.configurationIds.indexOf(p.configurationId)>=0);});
    if(!matches)return;
    p.usableChapterIds=p.usableChapterIds||[];
    var at=p.usableChapterIds.indexOf(meta.currentChapterId); if(p.usableChapterIds.indexOf(meta.chapterId)<0)p.usableChapterIds.splice(at>=0?at+1:p.usableChapterIds.length,0,meta.chapterId);
    p.provisionalChapterIds=p.provisionalChapterIds||[];uniq(p.provisionalChapterIds,meta.chapterId);
    p.v44ExpandedChapterIds=p.v44ExpandedChapterIds||[];uniq(p.v44ExpandedChapterIds,meta.chapterId);
    p.stateCounts=p.stateCounts||{};p.stateCounts.PROVISIONAL_OVERLAP=p.provisionalChapterIds.length;
  });
});
M.RESOLVED_PLANS=plans;if(M.CURRICULUM_INGEST_V1)M.CURRICULUM_INGEST_V1.resolvedPlans=plans;
var pidx={};plans.forEach(function(p){pidx[p.programmeId+'::'+p.configurationId]=p;});
M.planForV40=function(pid,cid){var p=pid||M.activeProgram(),c=cid||M.activeConfiguration(p);return pidx[p+'::'+c]||null;};
M.activeResolvedPlan=function(){return M.planForV40(M.activeProgram(),M.activeConfiguration());};

