M.v44GraphicHTML=function(ch,mode){var spec=PACK.visuals[ch.id]||{title:ch.title,labels:[],palette:['#6474FF','#1AC4A7']};return '<div class="v44-graphic '+(mode||'')+'">'+svgData(ch.id,spec)+'</div>';};
var mediaBase=M.mediaFor;M.V44_MEDIA_BY_CHAPTER={};
Object.keys(PACK.visuals).forEach(function(id){var c=M.chapter(id);if(!c)return;var spec=PACK.visuals[id],raw=svgData(id,spec);var m={id:'v44-'+id,type:'illustration',title:c.title,alt:'Fachgrafik zu '+c.title,caption:'Visuelle Orientierung für '+c.title,creator:'Stoffknacker',source:'local generated SVG',licence:'Stoffknacker original',licenceUrl:'',data:'data:image/svg+xml;charset=UTF-8,'+encodeURIComponent(raw),chapters:[id],provenance:'mnemika-original'};M.V44_MEDIA_BY_CHAPTER[id]=m;if(!M.MEDIA.some(function(x){return x.id===m.id;}))M.MEDIA.push(m);});
M.mediaFor=function(id){return M.V44_MEDIA_BY_CHAPTER[id]||(mediaBase?mediaBase(id):null);};

/* Presentation variety in every chapter. */
M.PRESENTATION_DATA=M.PRESENTATION_DATA||{};Object.keys(PACK.presentations).forEach(function(id){M.PRESENTATION_DATA[id]=PACK.presentations[id];});
M.v44ArrangeLesson=function(el){
 var lesson=el&&el.querySelector('.lesson'),main=lesson&&lesson.querySelector('.lesson-main'),rail=lesson&&lesson.querySelector('.rail');
 if(!lesson||!main||!rail)return;
 if(window.matchMedia('(max-width:760px)').matches){
  var head=main.querySelector('.lesson-head');
  if(rail.parentNode!==main||rail.nextElementSibling)main.appendChild(rail);
  rail.classList.add('v44-mobile-rail');
 }else{
  if(rail.parentNode!==lesson)lesson.appendChild(rail);
  rail.classList.remove('v44-mobile-rail');
 }
};
var lessonBase=M.renderLesson;M.renderLesson=function(el,c,D){var out=lessonBase.call(M,el,c,D);var existing=el.querySelector('.lesson-head .media.hero');if(existing)existing.classList.add('v44-hero-graphic');else if(!el.querySelector('.v44-hero-graphic')){var h=el.querySelector('.lesson-head h1');if(h){var d=document.createElement('div');d.className='v44-hero-graphic';d.innerHTML=M.v44GraphicHTML(c,'hero');h.insertAdjacentElement('afterend',d);}}var cards=M.PRESENTATION_DATA[c.id]||[];if(cards.length&&!el.querySelector('.v44-presentations')){var sec=document.createElement('section');sec.className='v44-presentations';sec.innerHTML='<header class="phase"><span class="phase-n">✦</span><div><h2>Anders sehen</h2><p>Grafik, Ablauf und Fehlvorstellung statt nur Fliesstext.</p></div></header>'+cards.map(function(x){return M.renderPresentation?M.renderPresentation(x.kind,x.data):'';}).join('');var t=el.querySelector('#ph-apply')||el.querySelector('#ph-test');if(t)t.parentNode.insertBefore(sec,t);}M.v44ArrangeLesson(el);return out;};
window.addEventListener('resize',function(){var el=document.getElementById('v-read');if(el&&!el.hidden)M.v44ArrangeLesson(el);});

/* Daily quests, chapter stars and local achievements. */
M.GAMIFICATION_V44={version:2,storageKey:'mnemika-v44-game',badges:[['first','Erster Schritt','Ein Kapitel bearbeiten','◆'],['streak3','Drei Tage dran','An drei Tagen lernen','◫'],['variety','Format-Profi','Vier Aufgabenformen lösen','✦'],['explorer','Fächerreise','In vier Fächern arbeiten','◎'],['perfect','Fünfer-Serie','Fünf Aufgaben in Folge lösen','★']]};
function gameState(){try{return JSON.parse(localStorage.getItem(M.GAMIFICATION_V44.storageKey)||'{}');}catch(e){return {};}}
function saveGame(g){try{localStorage.setItem(M.GAMIFICATION_V44.storageKey,JSON.stringify(g));}catch(e){}}
function day(){return new Date().toISOString().slice(0,10);}
function ensureDay(g){if(g.day===day())return g;var keep={badges:g.badges||{},totalOpened:g.totalOpened||0,totalAnswered:g.totalAnswered||0,subjectsEver:g.subjectsEver||{},typesEver:g.typesEver||{},days:g.days||[],correctRun:g.correctRun||0};keep.day=day();keep.opened=0;keep.answered=0;keep.subjects={};if(keep.days.indexOf(day())<0)keep.days.push(day());return keep;}
function earn(g){g.badges=g.badges||{};g.badges.first=(g.totalOpened||0)>=1;g.badges.streak3=(g.days||[]).length>=3;g.badges.variety=Object.keys(g.typesEver||{}).length>=4;g.badges.explorer=Object.keys(g.subjectsEver||{}).length>=4;g.badges.perfect=(g.correctRun||0)>=5;return g;}
M.v44Quests=function(){var g=earn(ensureDay(gameState()));saveGame(g);return [{id:'open',title:'Kapitel-Entdecker',target:2,value:g.opened||0,icon:'🧭'},{id:'answer',title:'Aufgaben-Sprint',target:8,value:g.answered||0,icon:'⚡'},{id:'subjects',title:'Fachwechsel',target:2,value:Object.keys(g.subjects||{}).length,icon:'🎨'}];};
M.v44Record=function(kind,c,qtype,correct){var g=ensureDay(gameState());if(kind==='open'){g.opened=(g.opened||0)+1;g.totalOpened=(g.totalOpened||0)+1;}if(kind==='answer'){g.answered=(g.answered||0)+1;g.totalAnswered=(g.totalAnswered||0)+1;g.typesEver=g.typesEver||{};if(qtype)g.typesEver[qtype]=1;g.correctRun=correct?(g.correctRun||0)+1:0;}if(c&&c.subject){g.subjects=g.subjects||{};g.subjects[c.subject]=1;g.subjectsEver=g.subjectsEver||{};g.subjectsEver[c.subject]=1;}saveGame(earn(g));};
var inlineBaseV44=M.inlineCheck;if(typeof inlineBaseV44==='function'){M.inlineCheck=function(host,q){var r=inlineBaseV44.apply(M,arguments);if(host&&q&&!host.dataset.v44Track){host.dataset.v44Track='1';var ob=new MutationObserver(function(){var fb=host.querySelector('.fb');if(!fb||host.dataset.v44Answered)return;host.dataset.v44Answered='1';var c=M.chapter&&M.chapter(q.lessonId||'');M.v44Record('answer',c,q.type,fb.classList.contains('ok'));ob.disconnect();});ob.observe(host,{childList:true,subtree:true});}return r;};}
M.v44SetActiveNav=function(v){var a=M.navGroup?M.navGroup(v):v;document.querySelectorAll('#v44-bottomnav button').forEach(function(b){var on=b.dataset.v===a;b.classList.toggle('active',on);b.setAttribute('aria-current',on?'page':'false');});};
var goBase=M.go;M.go=function(v,arg){var r=goBase.apply(M,arguments);setTimeout(function(){if(v==='read'){var c=M.chapter(typeof arg==='string'?arg:'');if(c)M.v44Record('open',c);}M.v44Mount();M.v44SetActiveNav(v);},0);return r;};
M.v44Mount=function(){var home=document.getElementById('v-home');if(home&&!home.hidden&&!home.querySelector('.v44-quests')){var q=M.v44Quests(),g=gameState();var s=document.createElement('section');s.className='v44-quests';s.innerHTML='<div class="v44-qhead"><div><span>Tagesmissionen</span><h2>Kleine Schritte, sichtbarer Fortschritt</h2></div><b>'+q.filter(function(x){return x.value>=x.target;}).length+'/3</b></div><div class="v44-qgrid">'+q.map(function(x){var p=Math.min(100,Math.round(x.value/x.target*100));return '<article><i>'+x.icon+'</i><div><b>'+e(x.title)+'</b><span>'+Math.min(x.value,x.target)+' von '+x.target+'</span><em><u style="width:'+p+'%"></u></em></div></article>';}).join('')+'</div><div class="v44-badges"><span>Abzeichen</span>'+M.GAMIFICATION_V44.badges.map(function(b){var on=g.badges&&g.badges[b[0]];return '<div class="'+(on?'earned':'locked')+'" title="'+e(b[2])+'"><i>'+b[3]+'</i><b>'+e(b[1])+'</b></div>';}).join('')+'</div>';var anchor=home.querySelector('.vhead,.homehero,.start-hero');if(anchor)anchor.insertAdjacentElement('afterend',s);else home.prepend(s);}M.v44BottomNav();};
M.v44BottomNav=function(){if(document.getElementById('v44-bottomnav'))return;var n=document.createElement('nav');n.id='v44-bottomnav';n.className='v44-bottomnav';n.setAttribute('aria-label','Mobile Hauptnavigation');n.innerHTML='<button data-v="learn" aria-label="Lernen"><b>'+((window.mnIkon?window.mnIkon('library'):'')||M.ICON&&M.ICON.learn||'')+'</b><span>Lernen</span></button><button data-v="practice" aria-label="Üben"><b>'+((window.mnIkon?window.mnIkon('pencil'):'')||M.ICON&&M.ICON.practice||'')+'</b><span>Üben</span></button><button data-v="pruefungen" aria-label="Prüfungen"><b>'+((window.mnIkon?window.mnIkon('clipboard'):'')||M.ICON&&M.ICON.test||'')+'</b><span>Prüfungen</span></button><button data-v="more" aria-label="Mehr"><b>'+((window.mnIkon?window.mnIkon('menu'):'')||M.ICON&&M.ICON.more||'')+'</b><span>Mehr</span></button>';n.querySelectorAll('button').forEach(function(b){b.onclick=function(){M.go(b.dataset.v);};});document.body.appendChild(n);M.v44SetActiveNav(M.navGroup?M.navGroup(document.body.dataset.view||'home'):'learn');};
setTimeout(M.v44Mount,300);

