M.openV44Requirement=function(id){var cfg=M.V44_REQUIREMENTS[id];if(!cfg)return;var key='mnemika-v44-req-'+id,old={};try{old=JSON.parse(localStorage.getItem(key)||'{}');}catch(e){}var d=document.createElement('dialog');d.className='v44-dialog';d.innerHTML='<form method="dialog"><header><div><span>Anforderung ergänzen</span><h2>'+e(cfg.title)+'</h2></div><button value="cancel" aria-label="Schliessen">×</button></header><p>Diese Angaben sind lernenden-, schul- oder sessionspezifisch. Sie werden nur lokal gespeichert und nicht als offiziell verifiziert behandelt.</p><div class="v44-fields">'+cfg.fields.map(function(f){return '<label><span>'+e(f[1])+'</span><textarea data-k="'+e(f[0])+'" rows="2">'+e(old[f[0]]||'')+'</textarea></label>';}).join('')+'</div><div class="row"><button class="btn" value="cancel">Abbrechen</button><button class="btn go" value="save">Lokal speichern</button></div></form>';document.body.appendChild(d);d.addEventListener('close',function(){if(d.returnValue==='save'){var v={updatedAt:new Date().toISOString()};d.querySelectorAll('[data-k]').forEach(function(x){v[x.dataset.k]=x.value.trim();});try{localStorage.setItem(key,JSON.stringify(v));}catch(e){}}d.remove();});d.showModal();};

var selfV44=M.selfTest;if(typeof selfV44==='function'){M.selfTest=function(){var r=selfV44.call(M)||[];/* Entfernt: hier wurde das Ergebnis einer fremden Pruefung nachtraeglich auf bestanden gesetzt. Eine Pruefung, die eine andere ueberschreibt, ist keine Pruefung. Das echte Ergebnis bleibt jetzt stehen. */r.push({name:'V44 curriculum series',pass:(M.chapters||[]).length>=241,detail:String((M.chapters||[]).length)});r.push({name:'V44 chapter graphics',pass:Object.keys(M.V44_MEDIA_BY_CHAPTER||{}).length>=241,detail:String(Object.keys(M.V44_MEDIA_BY_CHAPTER||{}).length)});r.push({name:'V44 presentation coverage',pass:Object.keys(M.PRESENTATION_DATA||{}).length>=241,detail:String(Object.keys(M.PRESENTATION_DATA||{}).length)});return r;};}
